/**
 * Roster is generated by: npm run generate-roster
 * Edit individual files under data/characters/, then re-run the script,
 * or edit data/roster.json directly for bulk changes.
 */
import type { Character, CharacterIndexEntry } from "./types.js";
import rosterJson from "../data/roster.json";
import indexJson from "../data/index.json";

export const CHARACTERS: Character[] = (rosterJson as Character[]).slice().sort((a, b) =>
  a.name.localeCompare(b.name)
);

export const CHARACTER_INDEX: CharacterIndexEntry[] =
  indexJson as CharacterIndexEntry[];

if (CHARACTERS.length === 0) {
  throw new Error("data/roster.json is empty — run npm run generate-roster");
}
